Author:     Geoff Lankow <geoff@darktrojan.net>
AuthorDate: Wed Dec 17 16:32:35 2025 +1300
Commit:     Geoff Lankow <geoff@darktrojan.net>
CommitDate: Wed Dec 17 16:32:35 2025 +1300

    Bug 2006550 - Use localised name instead of mailbox name in the status bar. r=mkmelin
    This has to jump through a few hoops to find the folder object and get the localised name,
    because nsImapProtocol only handles mailbox names instead of folder objects, but it'll do for now.

    Differential Revision: https://phabricator.services.mozilla.com/D276808

diff --git a/mailnews/imap/public/nsIImapMailFolderSink.idl b/mailnews/imap/public/nsIImapMailFolderSink.idl
index fd7dd7bad3f..3e5667bc3c0 100644
--- a/mailnews/imap/public/nsIImapMailFolderSink.idl
+++ b/mailnews/imap/public/nsIImapMailFolderSink.idl
@@ -106,7 +106,9 @@ interface nsIImapMailFolderSink : nsISupports {

   void headerFetchCompleted(in nsIImapProtocol aProtocol);
   void setBiffStateAndUpdate(in long biffState);
-  void progressStatusString(in nsIImapProtocol aProtocol, in string aMsgId, in wstring extraInfo);
+  void progressStatusString(in nsIImapProtocol aProtocol,
+                            in string aMsgId,
+                            in AUTF8String mailboxName);
   void percentProgress(in nsIImapProtocol aProtocol,
                        in ACString aFmtStringName, in long long aCurrentProgress,
                        in long long aMaxProgressProgressInfo);
diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 1948402fc58..1533d953fe9 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -2608,7 +2608,7 @@ NS_IMETHODIMP nsImapMailFolder::UpdateImapMailboxInfo(
     bool gettingNewMessages;
     GetGettingNewMessages(&gettingNewMessages);
     if (gettingNewMessages)
-      ProgressStatusString(aProtocol, "imapNoNewMessages", nullptr);
+      ProgressStatusString(aProtocol, "imapNoNewMessages", EmptyCString());
     SetPerformingBiff(false);
   }
   aSpec->GetNumMessages(&m_numServerTotalMessages);
@@ -6130,7 +6130,7 @@ nsresult nsImapMailFolder::DisplayStatusMsg(nsIImapUrl* aImapUrl,
 NS_IMETHODIMP
 nsImapMailFolder::ProgressStatusString(nsIImapProtocol* aProtocol,
                                        const char* aMsgName,
-                                       const char16_t* extraInfo) {
+                                       const nsACString& mailboxName) {
   nsString progressMsg;

   nsCOMPtr<nsIMsgIncomingServer> server;
@@ -6146,9 +6146,26 @@ nsImapMailFolder::ProgressStatusString(nsIImapProtocol* aProtocol,
     nsCOMPtr<nsIImapUrl> imapUrl;
     aProtocol->GetRunningImapURL(getter_AddRefs(imapUrl));
     if (imapUrl) {
-      if (extraInfo) {
+      if (!mailboxName.IsEmpty()) {
+        nsAutoString extraInfo;
+        nsCOMPtr<nsIMsgFolder> rootFolder;
+        server->GetRootFolder(getter_AddRefs(rootFolder));
+        if (rootFolder) {
+          nsCOMPtr<nsIMsgImapMailFolder> imapRootFolder =
+              do_QueryInterface(rootFolder);
+          nsCOMPtr<nsIMsgImapMailFolder> imapActualFolder;
+          imapRootFolder->FindOnlineSubFolder(mailboxName,
+                                              getter_AddRefs(imapActualFolder));
+          if (imapActualFolder) {
+            nsCOMPtr<nsIMsgFolder> actualFolder =
+                do_QueryInterface(imapActualFolder);
+            actualFolder->GetLocalizedName(extraInfo);
+          }
+        }
+
         nsString printfString;
-        nsTextFormatter::ssprintf(printfString, progressMsg.get(), extraInfo);
+        nsTextFormatter::ssprintf(printfString, progressMsg.get(),
+                                  extraInfo.get());
         progressMsg = printfString;
       }

@@ -6284,7 +6301,7 @@ nsImapMailFolder::SetUrlState(nsIImapProtocol* aProtocol,
   // no point in doing anything...
   if (!mPath) return NS_OK;
   if (!isRunning) {
-    ProgressStatusString(aProtocol, "imapDone", nullptr);
+    ProgressStatusString(aProtocol, "imapDone", EmptyCString());
     m_urlRunning = false;
     // if no protocol, then we're reading from the mem or disk cache
     // and we don't want to end the offline download just yet.
diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index 70a157a301c..55af472b625 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -5312,7 +5312,7 @@ void nsImapProtocol::ProgressEventFunctionUsingName(const char* aMsgName) {
     return;
   }
   if (m_imapMailFolderSink && !m_lastProgressStringName.Equals(aMsgName)) {
-    m_imapMailFolderSink->ProgressStatusString(this, aMsgName, nullptr);
+    m_imapMailFolderSink->ProgressStatusString(this, aMsgName, EmptyCString());
     m_lastProgressStringName.Assign(aMsgName);
     // who's going to free this? Does ProgressStatusString complete
     // synchronously?
@@ -5320,14 +5320,10 @@ void nsImapProtocol::ProgressEventFunctionUsingName(const char* aMsgName) {
 }

 void nsImapProtocol::ProgressEventFunctionUsingNameWithString(
-    const char* aMsgName, const char* aExtraInfo) {
+    const char* msgName, const char* mailboxName) {
   if (m_imapMailFolderSink) {
-    nsString unicodeStr;
-    nsresult rv =
-        CopyFolderNameToUTF16(nsDependentCString(aExtraInfo), unicodeStr);
-    if (NS_SUCCEEDED(rv))
-      m_imapMailFolderSink->ProgressStatusString(this, aMsgName,
-                                                 unicodeStr.get());
+    m_imapMailFolderSink->ProgressStatusString(this, msgName,
+                                               nsCString(mailboxName));
   }
 }

diff --git a/mailnews/imap/src/nsImapProtocol.h b/mailnews/imap/src/nsImapProtocol.h
