@@ -296,8 +296,8 @@ class nsImapProtocol : public nsIImapProtocol,
   void AlertCertError(nsITransportSecurityInfo* securityInfo);

   void ProgressEventFunctionUsingName(const char* aMsgId);
-  void ProgressEventFunctionUsingNameWithString(const char* aMsgName,
-                                                const char* aExtraInfo);
+  void ProgressEventFunctionUsingNameWithString(const char* msgName,
+                                                const char* mailboxName);
   void PercentProgressUpdateEvent(nsACString const& fmtStringName,
                                   int64_t currentProgress, int64_t maxProgress);
   void ShowProgress();
diff --git a/mailnews/imap/src/nsSyncRunnableHelpers.cpp b/mailnews/imap/src/nsSyncRunnableHelpers.cpp
index 7601ad4c97b..13acb7c4e73 100644
--- a/mailnews/imap/src/nsSyncRunnableHelpers.cpp
+++ b/mailnews/imap/src/nsSyncRunnableHelpers.cpp
@@ -366,7 +366,7 @@ NS_SYNCRUNNABLEMETHOD1(ImapMailFolderSink, HeaderFetchCompleted,
                        nsIImapProtocol*)
 NS_SYNCRUNNABLEMETHOD1(ImapMailFolderSink, SetBiffStateAndUpdate, int32_t)
 NS_SYNCRUNNABLEMETHOD3(ImapMailFolderSink, ProgressStatusString,
